 function plan(){const c=current(),p=progress();return `<section class="rx-panel">${section('plan','Ваше решение','Укажите порядок работы, маршрут и последовательность действий.')}<div class="rx-role-note"><strong>${esc(c.role.title)}</strong><p>${esc(c.role.text)}</p></div>${coach('plan')}${choices('procedure','Порядок рассмотрения',c.procedures,p.procedure)}${choices('route','Кому и для чего передать материалы?',c.routes,p.route)}<h3>Соберите план</h3><p class="rx-small">Выбирайте необходимые действия. Порядок меняется кнопками со стрелками. Выбор всех действий не даёт максимальный балл.</p><div class="rx-plan-pool">${opts(c.actions.filter(a=>!p.actions.includes(a.id)),'actions').map(a=>button(a.title,'add-action','small',`data-id="${a.id}" ${locked()?'disabled':''}`,'add')).join('')}</div><ol class="rx-action-list">${p.actions.map((id,i)=>{const a=c.actions.find(a=>a.id===id);return `<li><span>${esc(a.title)}</span><div class="rx-order-controls">${button('','move-action','icon-only',`data-id="${id}" data-delta="-1" aria-label="Поднять: ${esc(a.title)}" ${locked()||i===0?'disabled':''}`,'up')}${button('','move-action','icon-only',`data-id="${id}" data-delta="1" aria-label="Опустить: ${esc(a.title)}" ${locked()||i===p.actions.length-1?'disabled':''}`,'down')}${button('','remove-action','icon-only',`data-id="${id}" aria-label="Убрать: ${esc(a.title)}" ${locked()?'disabled':''}`,'close')}</div></li>`;}).join('')}</ol>${choices('trap',c.trap.text,c.trap.options,p.trap)}${button(previewText?'Скрыть проект сообщения':'Посмотреть проект сообщения','reply','soft','','doc')}${previewText?`<div class="rx-document rx-reply">${localizedReplyParts({...c,title:displayTitle(c)},p,presenter?.getTranslator()||fallbackTranslator()).map(line=>line.map(part=>part.userContent?`<span data-rx-user-content>${esc(part.text)}</span>`:esc(part.text)).join('')).join('<br>')}</div>`:''}<div class="rx-actions-footer">${locked()?button('К зафиксированному решению','receipt','primary','','arrow'):button(policy().feedback?'Проверить в обучении':'Подтвердить решение','commit','primary','','check')}${!locked()?button('Пропустить основное решение','skip','ghost'):''}</div><p class="rx-small">${policy().feedback?'В обучении разбор доступен сразу. Оценка не записывается.':'После подтверждения ответы этого дела изменить нельзя. Отдельные пустые поля допустимы; за них баллы не начисляются.'}</p></section>`;}
